-- ============================================================================
-- D4: Data-Driven Production Forecasting joins the catalogue, the FOURTH
-- course of the Data & AI module.
--
-- Catalogue row (module 'data_ai'; path_order 69, directly above D3
-- facies at 68; prereq_slug NULL, as D1, D2 and D3 carry it: whether D4
-- requires an earlier course is a go-live decision; school left at its
-- default) plus the three capstones and their eighteen graded fields,
-- generated by tools/course-waves/forecastml/gen_course.py from the ENGINE'S
-- OWN RUN (d4_capstone.mjs through the vendored engines/dataai/forecast.js and
-- engines/dca/arps.js), which it refuses to write unless fields.json carries
-- exactly that run's values and the tolerance gradedTolerance.js derives. Deep
-- seeds are three separate migrations; the go-live is a fifth and is HELD
-- until a NextGen production upload carries the route
-- /dashboard/apps/forecastml, because the 78 lessons, the teaching lab
-- (forecastLab.js), its three explorer panels and the capstone case files ship
-- in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. A data-driven forecast extends a rate series
-- from its own history, and it is worth something only when it is tested on
-- months it never saw, so the course teaches smoothing a rate series into a
-- forecast (Associate), testing a forecast honestly (Professional), and
-- uncertainty, the Arps baseline and the engine's rules (Expert), and grades
-- each tier on its own question with numbers the engine returns.
--
-- THE ENGINE. engines/dataai/forecast.js, vendored sha-identical with
-- petrolord-engines 1dfdd60, with engines/dca/arps.js for the Arps baseline
-- and lib/stats for mulberry32 and the quantile. Simple, Holt and damped
-- exponential smoothing start at the first observation and fit by the least
-- one-step SSE (a grid, then a compass search, phi fitted in 0.8 to 0.98); an
-- error is actual minus forecast; MASE divides by the in-sample lag-m naive
-- MAE of the training months; the residual bootstrap draws the scored
-- residuals without centring on one mulberry32 stream; P90 is the low case.
--
-- WHAT IS GRADED. AGULU (Associate) grades a fitted ses alpha, a Holt MSE with
-- its parameters given, a fitted Holt beta and forecast, and a fitted damped
-- phi and forecast; NANKA (Professional) grades a hold-out sMAPE, MASE and
-- mean error through a shut-in, a refitted backtest's pooled RMSE, the held
-- backtest's pooled MASE and a by-horizon MAE; UMUNZE (Expert) grades a
-- bootstrap P90 (low), P10 (high) and P50, an Arps Di per month, and a
-- comparison's arps MASE and best MASE. Every value is a return value of the
-- engine, and the data it was run on is in the case file the prompt names.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, a label or
-- a case file, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('forecastml', 'Data-Driven Production Forecasting', 'data_ai', 69, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'forecastml', 'beginner', 'associate',
  'AGULU, 2 producing wells, 42 months each',
  'Smoothing a rate series into a forecast',
  'AGULU, a field of 2 producing wells, AGULU-1 and AGULU-2, with 42 months each of monthly average oil rate in bbl/d, oldest month first. One case file comes with this capstone. agulu_rates.csv carries 84 rows, in well order and in month order within each well: the well name, the month counted from 0, and the monthly average oil rate in bbl/d. No month is missing and no month is 0. Fit on every month of the well named, with only the parameters stated here given. Report six values: the alpha that simple exponential smoothing fits on AGULU-2; the MSE, in (bbl/d)^2, of Holt''s linear trend on AGULU-1 with alpha 0.4 and beta 0.15 given; the beta that Holt''s linear trend fits on AGULU-1 with alpha and beta both left free; that fitted Holt forecast at step 12, in bbl/d; the phi that the damped trend fits on AGULU-1 with alpha, beta and phi all left free; and that fitted damped forecast at step 24, in bbl/d. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','agulu2_ses_alpha', 'label','The alpha simple exponential smoothing fits on AGULU-2', 'unit','dimensionless', 'expected',0.5554212108254432, 'tol',5e-07),
    jsonb_build_object('key','agulu1_holt_fixed_mse_bopd2', 'label','The MSE of holt on AGULU-1 with alpha 0.4 and beta 0.15 given', 'unit','(bbl/d)^2', 'expected',1557.116998731944, 'tol',5e-07),
    jsonb_build_object('key','agulu1_holt_beta', 'label','The beta holt fits on AGULU-1, alpha and beta left free', 'unit','dimensionless', 'expected',0.257987117767334, 'tol',5e-07),
    jsonb_build_object('key','agulu1_holt_forecast_h12_bopd', 'label','The fitted holt forecast of AGULU-1 at step 12', 'unit','bbl/d', 'expected',178.71280696811394, 'tol',1e-05),
    jsonb_build_object('key','agulu1_damped_phi', 'label','The phi the damped trend fits on AGULU-1, every parameter left free', 'unit','dimensionless', 'expected',0.9588943874835968, 'tol',5e-07),
    jsonb_build_object('key','agulu1_damped_forecast_h24_bopd', 'label','The fitted damped forecast of AGULU-1 at step 24', 'unit','bbl/d', 'expected',165.93091668046597, 'tol',0.0001)
  )
),
(
  'forecastml', 'intermediate', 'professional',
  'NANKA, 2 producing wells, one shut in',
  'Testing a forecast honestly',
  'NANKA, a field of 2 producing wells, NANKA-1 and NANKA-2, with 48 months of NANKA-1 and 50 months of NANKA-2 of monthly average oil rate in bbl/d, oldest month first. One case file comes with this capstone. nanka_rates.csv carries 98 rows, in well order and in month order within each well: the well name, the month counted from 0, and the monthly average oil rate in bbl/d. NANKA-1 was shut in for months 40 and 41, at rate 0; no other month is missing or 0. Report six values. First, the sMAPE, in percent, of the damped trend fitted on NANKA-1 months 0 to 35, every parameter left free, forecasting 12 steps and scored against months 36 to 47. Second, the MASE of the same forecast with months 0 to 35 as the in-sample series and m 1. Third, its mean error, actual minus forecast, in bbl/d. Fourth, the pooled RMSE, in bbl/d, of a rolling-origin backtest of Holt''s linear trend on NANKA-2 from first origin 18, horizon 6, step 4, refitted at every origin, m 1. Fifth, the pooled MASE of the same backtest with refit false, the parameters held from the first window. Sixth, the MAE, in bbl/d, at step 6 ahead of the refitted backtest. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nanka1_holdout_damped_smape_pct', 'label','The sMAPE of the damped forecast of NANKA-1 over months 36 to 47', 'unit','percent', 'expected',43.676026323068925, 'tol',1e-05),
    jsonb_build_object('key','nanka1_holdout_damped_mase', 'label','The MASE of that forecast, m 1', 'unit','dimensionless', 'expected',2.162820964083014, 'tol',5e-07),
    jsonb_build_object('key','nanka1_holdout_damped_me_bopd', 'label','The mean error of that forecast', 'unit','bbl/d', 'expected',-84.76609714686862, 'tol',1e-05),
    jsonb_build_object('key','nanka2_backtest_holt_rmse_bopd', 'label','The pooled RMSE of the refitted holt backtest of NANKA-2', 'unit','bbl/d', 'expected',32.871937503375555, 'tol',1e-05),
    jsonb_build_object('key','nanka2_backtest_holt_held_mase', 'label','The pooled MASE of the same backtest with refit false', 'unit','dimensionless', 'expected',0.6195859568435137, 'tol',5e-07),
    jsonb_build_object('key','nanka2_backtest_holt_step6_mae_bopd', 'label','The MAE at step 6 of the refitted backtest', 'unit','bbl/d', 'expected',33.483471338670675, 'tol',1e-05)
  )
),
(
  'forecastml', 'advanced', 'expert',
  'UMUNZE, 2 producing wells, one shut in and restarted',
  'Uncertainty, the Arps baseline and the engine''s rules',
  'UMUNZE, a field of 2 producing wells, UMUNZE-1 and UMUNZE-2, with 45 months of UMUNZE-1 and 52 months of UMUNZE-2 of monthly average oil rate in bbl/d, oldest month first. One case file comes with this capstone. umunze_rates.csv carries 97 rows, in well order and in month order within each well: the well name, the month counted from 0, and the monthly average oil rate in bbl/d. UMUNZE-2 was shut in for months 28 to 30, at rate 0, and restarted after a workover; no other month is missing or 0. Report six values. First, the P90 (low) at step 12 of the residual bootstrap of the damped trend fitted on all of UMUNZE-1, every parameter left free, h 12, 1000 paths, seed 29, nonNegative true. Second, the P10 (high) at step 12 of the same run. Third, the P50 at step 6 of the same run. Fourth, the Di, per month, of the Arps baseline fitted on all of UMUNZE-1 with the model Auto-Select. Fifth and sixth, from a comparison of ses, holt and damped with the Arps baseline on UMUNZE-2, first origin 33, horizon 6, step 3, refit true, m 1, the Arps model Auto-Select, ranked by MASE: the MASE of the arps row, and the MASE of the method the ranking puts first. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','umunze1_damped_p90_h12_bopd', 'label','The P90 (low) at step 12 of the damped bootstrap of UMUNZE-1', 'unit','bbl/d', 'expected',77.53186379015042, 'tol',0.0001),
