    jsonb_build_object('key','umunze1_arps_di_per_month', 'label','The Arps Di of UMUNZE-1, Auto-Select', 'unit','per month', 'expected',0.053067976143630034, 'tol',5e-07),
    jsonb_build_object('key','umunze2_compare_arps_mase', 'label','The MASE of the arps row in the comparison on UMUNZE-2', 'unit','dimensionless', 'expected',0.4876127603859749, 'tol',5e-07),
    jsonb_build_object('key','umunze2_compare_best_mase', 'label','The MASE of the method the comparison ranks first', 'unit','dimensionless', 'expected',0.3618511672231542, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
